import type { Matter, MatterDocumentRef, MatterSummary } from "../../types/portfolio";
import summaries from "./summaries.json";

// Light records for list/search/dashboard — generated by sync:summaries
// through publishMatter(). The browser never globs the split laptop folders.
export const cases = summaries as MatterSummary[];

const publishLoaders = import.meta.glob("./publish/*.json") as Record<
  string,
  () => Promise<{ default: Matter & { documents?: MatterDocumentRef[] } }>
>;

function padded(number: number): string {
  return String(number).padStart(2, "0");
}

export function matterFileKey(number: number): string {
  return `./publish/${padded(number)}.json`;
}

function labelFromPath(docPath: string): string {
  const base = docPath.split("/").pop() ?? docPath;
  return base.replace(/\.pdf$/i, "").replace(/\.docx$/i, "").trim() || base;
}

function finishMatter(raw: Matter & { documents?: MatterDocumentRef[] }): Matter {
  const documents = (raw.documents ?? []).map((doc) => ({
    path: doc.path,
    label: doc.label?.trim() || labelFromPath(doc.path),
    ...(typeof doc.filed === "boolean" ? { filed: doc.filed } : {}),
  }));
  return {
    ...raw,
    documents,
    evidenceCount: raw.evidenceCount ?? 0,
    documentCount: raw.documentCount ?? documents.length,
  };
}

export function loadMatter(number: number): Promise<Matter> {
  const loader = publishLoaders[matterFileKey(number)];
  if (!loader) {
    return Promise.reject(new Error(`No publish record for matter ${number} — run npm run sync:summaries`));
  }
  return loader().then((mod) => finishMatter(mod.default));
}

export function getMatterSummary(number: number): MatterSummary | undefined {
  return cases.find((matter) => matter.number === number);
}
